(()=>{let batches=[],loading=false,project='',submitting=false;const id=x=>x.target.shot_id||x.target.id;function cfg(){return data.filmUpscale??={target:1920,use:true};}function records(){return batches.flatMap(b=>b.items.map(i=>({...i,target:b.target,batch_id:b.id,batch_status:b.status})));}function match(x){return records().find(i=>i.video_id===(x.video?.id||x.video?.job_id)&&i.target_id===id(x)&&i.target===Number(cfg().target)&&i.status==='completed'&&i.job_id);}function selected(x){return cfg().selection?.[id(x)]!==false;}function row(x,index){const v=x.video,job=records().find(i=>i.target===Number(cfg().target)&&i.video_id===(v?.id||v?.job_id)&&i.target_id===id(x)),ready=match(x),disabled=!v?.video_url||submitting||batches.some(b=>b.status==='running');const label=job?(job.status==='completed'?'已放大 · '+job.width+' × '+job.height:job.status==='skipped'?'已达到目标尺寸':job.status==='failed'?'失败：'+job.error:job.status==='cancelled'?'已停止':job.phase||'等待放大'):v?v.width+' × '+v.height:'未生成';return '<label style="display:inline-flex;flex:0 0 auto;flex-direction:column;align-items:flex-start;gap:6px;width:auto;padding:12px 16px;border-radius:12px;border:1px solid '+(selected(x)&&v?.video_url?'#658f81':'#30404f')+';background:#111b27;cursor:pointer"><span style="display:flex;align-items:center;gap:8px;white-space:nowrap"><input type="checkbox" data-shot-select="'+esc(id(x))+'" '+(selected(x)&&v?.video_url?'checked':'')+' '+(disabled?'disabled':'')+' style="width:18px;height:18px;flex:0 0 18px;margin:0">'+(index+1)+'. '+esc(id(x))+(ready?' ✓':'')+'</span><small style="max-width:240px;overflow-wrap:anywhere">'+esc(label)+'</small></label>';}
function update(){const box=document.querySelector('#filmShotUpscale');if(!box)return;const items=filmItems(),running=batches.find(b=>b.status==='running'),chosen=items.filter(x=>x.video?.video_url&&selected(x));box.querySelector('[data-rows]').innerHTML=items.map(row).join('');box.querySelector('[data-all]').disabled=submitting||!!running||!chosen.length;box.querySelector('[data-all]').textContent='放大所选分镜（'+chosen.length+'）';box.querySelector('[data-stop]').hidden=!running;box.querySelector('[data-progress]').textContent=running?'已完成 '+running.items.filter(i=>['completed','skipped'].includes(i.status)).length+' / '+running.items.length+' 个 · 逐个处理，可离开页面':'已选 '+chosen.length+' / '+items.filter(x=>x.video?.video_url).length+' 个可用分镜';box.querySelectorAll('[data-shot-select]').forEach(el=>el.onchange=()=>{cfg().selection??={};cfg().selection[el.dataset.shotSelect]=el.checked;save();update();});const allSelect=box.querySelector('[data-select-all]'),available=items.filter(x=>x.video?.video_url);allSelect.checked=available.length>0&&chosen.length===available.length;allSelect.indeterminate=chosen.length>0&&chosen.length<available.length;allSelect.disabled=submitting||!!running||!available.length;}
async function load(){if(loading||!data.project_id)return;loading=true;const p=data.project_id;try{const result=await frontFetch('/api/shot-upscale?project_id='+encodeURIComponent(p));if(p!==data.project_id)return;batches=result;project=p;update();}catch(e){const box=document.querySelector('#filmShotUpscale [data-progress]');if(box)box.textContent=e.message;}finally{loading=false;}}
async function submit(items){if(submitting)return;submitting=true;try{await flushDisk();if(diskConflict||lastDiskData!==JSON.stringify(data))throw Error('请先完成项目保存');await frontFetch('/api/shot-upscale',{project_id:data.project_id,target:Number(cfg().target),port:(typeof videoGenerationPort==='function'?videoGenerationPort():Number(localStorage.getItem('frame-comfy-port')||8188)),items:items.filter(x=>x.video?.video_url).map(x=>({target_id:id(x),video_id:x.video.id||x.video.job_id}))});await load();}catch(e){toast(e.message);}finally{submitting=false;update();}}
function draw(){if(tab!==5)return;const anchor=document.querySelector('#panel > .card');if(!anchor)return;if(project!==data.project_id){batches=[];project=data.project_id;}const c=cfg(),box=document.createElement('section');box.id='filmShotUpscale';box.className='card';box.style.marginBottom='20px';box.innerHTML='<h3>分镜高清放大</h3><p class="subtle">跟随当前选择的GPU放大分镜，再预览或合成。保持原比例与原声，已完成的同尺寸版本自动跳过。</p><div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap"><label>目标尺寸<select data-target><option value="1920">1080P · 长边1920</option><option value="2560">2K · 长边2560</option><option value="3840">4K · 长边3840</option></select></label></div><label style="display:flex;align-items:center;gap:8px;margin:16px 0"><input type="checkbox" data-use style="width:20px;flex:none">预览和合成优先使用所选尺寸的放大版</label><p class="subtle">未完成放大的分镜仍用原视频；混用不同尺寸时，成片沿用第一个分镜的尺寸。放大不会覆盖原视频。</p><label style="display:inline-flex;align-items:center;gap:8px;width:auto;margin:16px 0 0"><input type="checkbox" data-select-all style="width:18px;height:18px;flex:0 0 18px;margin:0">全选分镜</label><div style="display:flex;gap:10px;flex-wrap:wrap;margin:16px 0" data-rows></div><p data-progress></p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="primary" data-all>放大所选分镜</button><button data-stop hidden>停止放大</button></div>';anchor.before(box);box.querySelector('[data-target]').value=c.target;box.querySelector('[data-target]').onchange=e=>{c.target=Number(e.target.value);save();update();};box.querySelector('[data-use]').checked=c.use!==false;box.querySelector('[data-use]').onchange=e=>{c.use=e.target.checked;save();};box.querySelector('[data-all]').onclick=()=>submit(filmItems().filter(selected));box.querySelector('[data-select-all]').onchange=e=>{cfg().selection=Object.fromEntries(filmItems().map(x=>[id(x),e.target.checked]));save();update();};box.querySelector('[data-stop]').onclick=async()=>{const b=batches.find(b=>b.status==='running');if(b)try{await frontFetch('/api/shot-upscale/'+b.id+'/stop',{});await load();}catch(e){toast(e.message);}};update();load();}
const oldFetch=frontFetch;frontFetch=async function(url,body){if(url==='/api/film-export'&&body?.items&&cfg().use!==false){await load();const current=filmItems();body={...body,items:body.items.map(i=>{const x=current.find(x=>id(x)===i.target_id&&(x.video?.id||x.video?.job_id)===i.video_id);return{...i,upscale_job_id:x?match(x)?.job_id:undefined};})};}return oldFetch(url,body);};const oldStage=stage;stage=function(){oldStage();draw();};setInterval(()=>{if(tab===5)load();},3000);render();})();